head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
// 상장관련공통함수
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.vScrenID = "ULDSTF35700.xml";
scwin.gParamObj = null;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //child에 넘길 param용 

//신규기업 feedback 관리  검색 
scwin.fn_list_sync = function() {
    var isur_cd = txb_ISUR_CD.getValue();
    var task_dd_s = edt_SDate.GetSelClipText(0, 8);
    var task_dd_e = edt_EDate.GetSelClipText(0, 8);
    var url = "/NewListedCompanyAnalysisManagement.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=getNewCorpManagement&For=NML&inputMessageId=NLCM_IN&outputMessageId=NLCM_OUT_NML" + "&ISUR_CD=" + isur_cd + "&TASK_DD_S=" + task_dd_s + "&TASK_DD_E=" + task_dd_e;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List); // 그리드명을 표기

};
scwin.fn_editGovCorpInfo = async function(GridID, row, colid) {
    //var CMD = "R";	
    if (row < 1) return;
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..
    var vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
    if (scwin.fn_setParam(vISUR_CD)) // formal arguments

    {
        await $c.frame.CreateDialogFrame("REP_ISU_SRT_CD", "../lstmgt/ULDSTF35701.gfm", "신규상장기업 피드백 분석자료관리", 100, 10, 917, 710, "window");
        //fn_list_sync();

    }
};





// child에 넘길 paramObj Update
scwin.fn_setParam = function() {
    var argv = fn_setParam.arguments;
    var argc = fn_setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (var i = 0; i < argc; i++) // actual arguments

    {
        //eval("gParamObj.param" + i + " = argv[" + i + "]");
        scwin.gParamObj[i] = argv[i];
    }
    return true;
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List); //데이터 로딩중닫기 및 조회없음 처리		

};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin(0, grd_List); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.img_search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.grd_List_OnDblClick = function(row, colid) {
    scwin.fn_editGovCorpInfo(grd_List, row, colid);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.img_toExcel_onclick = function() {
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_List, "신규상장기업 피드백 분석자료", "", "8");
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.btn_ISUR_CD_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.gform_onload = function() {
    //round처리
    $c.libRoundPanel.PanelToGroupBox(panel_Top);

    //오늘날짜로 초기화시킨다.
    var today = $c.ut.cGetToday("yyyymmdd");
    $c.stf.setObjectValue(edt_SDate, $c.ut.cGetMinusDate2(today, 365 * 10)); // 일년 날짜);	
    $c.stf.setObjectValue(edt_EDate, today);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    Grd_com_isur.style.zIndex = 30;
    scwin.fn_list_sync();
};
